mapper.select:
SELECT COUNT(DISTINCT user_id)
FROM user_login_logs
WHERE created_at >= #{start}
  AND created_at < #{end}

SELECT DATE_FORMAT(created_at, '%Y-%m-%d') AS label, COUNT(DISTINCT user_id) AS value
FROM user_login_logs
WHERE created_at >= #{start}
  AND created_at < #{end}
GROUP BY DATE_FORMAT(created_at, '%Y-%m-%d')
ORDER BY label ASC
